// 1) Producer Contract (TypeScript + Zod) - Lưu tại packages/contracts/lead_created.v2.ts
import { z } from 'zod';

export const LeadCreatedContractV2 = z.object({
  schema_version: z.literal('2.0.0'),
  event_id: z.string().uuid(),
  occurred_at: z.string().datetime(),
  lead_id: z.string().min(6),
  phone_e164: z.string().regex(/^\+84[35789]\d{8}$/, 'Must be strict VN E.164'),
  // Không chấp nhận chuỗi mơ hồ; bắt buộc số nguyên VNĐ không âm
  budget_vnd: z.number().int().nonnegative(),
  lead_source: z.enum(['meta_form', 'web_3d', 'zalo_oa', 'pos_qr']),
  // Giữ trường legacy trong giai đoạn Expand-and-Contract (deprecated)
  lead_budget_vnd: z.number().int().nonnegative().optional(),
}).strict();

export type LeadCreatedV2 = z.infer<typeof LeadCreatedContractV2>;

export function publishLeadEventSafe(rawInput: unknown) {
  const parsed = LeadCreatedContractV2.parse(rawInput); // Ném lỗi ngay tại nguồn nếu sai Contract
  return queue.add('lead.created.v2', parsed);
}

# 2) Consumer Contract (Python + Pydantic v2) - Cấm fallback 'or 0' làm hỏng AI Scorer
from pydantic import BaseModel, ConfigDict, Field, ValidationError
from typing import Literal

class LeadCreatedV2(BaseModel):
    model_config = ConfigDict(extra='forbid', strict=True)
    schema_version: Literal['2.0.0']
    event_id: str
    occurred_at: str
    lead_id: str
    phone_e164: str = Field(pattern=r'^\+84[35789]\d{8}$')
    budget_vnd: int = Field(ge=0)
    lead_source: Literal['meta_form', 'web_3d', 'zalo_oa', 'pos_qr']
    lead_budget_vnd: int | None = None

def consume_for_ai_prescorer(raw_payload: dict):
    try:
        lead = LeadCreatedV2.model_validate(raw_payload)
    except ValidationError as exc:
        send_to_quarantine_dlq(raw_payload, reason=exc.errors())
        trigger_ops_alert(f'SCHEMA_CONTRACT_BREACH: {exc.error_count()} errors')
        raise
    return run_prescorer_model(budget_vnd=lead.budget_vnd, source=lead.lead_source)
